            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented basics.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and education. She holds a PhD from MIT and has published extensively on programming pedagogy.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Instructor = "Dr. James Wright", InstructorBio = "Dr. Wright is an ACM Fellow specializing in algorithm optimization. He previously worked at Google Research.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, Code = "CS 310", Title = "Database Systems", Description = "Principles of database design, SQL, normalization, transactions, and modern NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Instructor = "Dr. Maria Santos", InstructorBio = "Dr. Santos spent a decade at Oracle before joining academia. Her research focuses on distributed database systems.", IsFeatured = false, DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 2, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Instructor = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with a focus on making calculus accessible to all students.", IsFeatured = true, DepartmentName = "Mathematics" },
            new() { Id = 5, DepartmentId = 2, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Instructor = "Dr. Emily Park", InstructorBio = "Dr. Park's research bridges pure mathematics and machine learning applications.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Fri Lab", Instructor = "Dr. Alan Foster", InstructorBio = "Dr. Foster is a former NASA researcher with expertise in classical mechanics and astrophysics.", IsFeatured = true, DepartmentName = "Physics" },
            new() { Id = 7, DepartmentId = 3, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Instructor = "Dr. Lisa Chang", InstructorBio = "Dr. Chang has published over 50 papers on electromagnetic theory and its engineering applications.", IsFeatured = false, DepartmentName = "Physics" },
