## 8. Create pages

### Replace `Components/Pages/Home.razor`:
```razor
@page "/"
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<h1>Welcome to the Course Catalog</h1>
<p>Browse our departments and courses, or submit an enrollment request.</p>

<section>
    <h2>Departments</h2>
    <div class="dept-links">
        @foreach (var dept in Catalog.GetDepartments())
        {
            <a class="dept-link" href="/courses?departmentId=@dept.Id">@dept.Name (@dept.Code)</a>
        }
    </div>
</section>

<section>
    <h2>Featured Courses</h2>
    <div class="card-grid">
        @foreach (var course in Catalog.GetFeaturedCourses())
        {
            <div class="card">
                <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                <p class="meta">@course.Code · @course.Credits credits · @course.DepartmentName</p>
                <p>@course.Description</p>
                <span class="badge">Featured</span>
            </div>
        }
    </div>
</section>
```

### Create `Components/Pages/Courses.razor`:
```razor
@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" class="filter-bar" action="/courses">
    <div class="field">
        <label for="search">Search</label>
        <input type="text" id="search" name="search" value="@Search" placeholder="Title, code, or instructor" />
    </div>
    <div class="field">
        <label for="departmentId">Department</label>
        <select id="departmentId" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <button type="submit">Filter</button>
</form>

@{
    var courses = Catalog.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <p>No courses match your search criteria.</p>
}
else
{
    <p>Showing @courses.Count course(s)</p>
    <div class="card-grid">
        @foreach (var course in courses)
        {
            <div class="card">
                <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                <p class="meta">@course.Code · @course.Credits credits · @course.Schedule</p>
                <p>@course.Description</p>
                <p class="meta">Instructor: @course.Instructor</p>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}
```

