html, body {
    margin: 0;
    padding: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    font-size: 16px;
    line-height: 1.6;
    color: #333;
}

h1, h2, h3 {
    color: #1a237e;
}

a {
    color: #1565c0;
}

a:hover {
    color: #0d47a1;
}

/* Cards */
.card-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 1.5rem;
    margin: 1.5rem 0;
}

.card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    background: white;
    transition: box-shadow 0.2s;
}

.card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.card h3 {
    margin-top: 0;
}

.card .meta {
    color: #666;
    font-size: 0.9rem;
}

/* Badges */
.badge {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 600;
    background: #e3f2fd;
    color: #1565c0;
}

/* Search / Filter bar */
.filter-bar {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
    margin-bottom: 1.5rem;
    align-items: end;
}

.filter-bar .field {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.filter-bar label {
    font-size: 0.85rem;
    font-weight: 600;
    color: #555;
}

.filter-bar input,
.filter-bar select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.filter-bar button {
    padding: 0.5rem 1.25rem;
    background: #1a237e;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.filter-bar button:hover {
    background: #283593;
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 600;
    color: #444;
}

.form-group input,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.btn-primary {
    padding: 0.6rem 1.5rem;
    background: #1a237e;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

.btn-primary:hover {
    background: #283593;
}

/* Detail page */
.detail-header {
    margin-bottom: 2rem;
}

.detail-header .code {
    color: #666;
    font-size: 1.1rem;
}

.detail-section {
    margin-bottom: 1.5rem;
}

.detail-section h2 {
    font-size: 1.2rem;
    border-bottom: 2px solid #e3f2fd;
    padding-bottom: 0.5rem;
}

.info-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1rem;
    margin: 1rem 0;
}

.info-item {
    background: #f5f5f5;
    padding: 1rem;
    border-radius: 6px;
}

.info-item .label {
    font-size: 0.8rem;
    text-transform: uppercase;
    color: #666;
    font-weight: 600;
}

.info-item .value {
    font-size: 1.1rem;
    margin-top: 0.25rem;
}

/* Alert */
.alert-success {
    background: #e8f5e9;
    border: 1px solid #a5d6a7;
    color: #2e7d32;
    padding: 1rem;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

/* Department links */
.dept-links {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin: 1rem 0;
}

.dept-link {
    padding: 0.5rem 1rem;
    background: #f5f5f5;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    text-decoration: none;
    color: #1a237e;
    font-weight: 500;
}

.dept-link:hover {
    background: #e3f2fd;
    border-color: #90caf9;
}
EOF

