```razor
@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>

@if (submitted)
{
    <div class="alert-success">
        <strong>Request Submitted!</strong> Your enrollment request has been received. You will be notified once it is processed.
    </div>
    <p><a href="/courses">Browse more courses</a></p>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <form method="post" @formname="enrollment">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" required />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="Model.CourseId" required>
                <option value="">— Select a course —</option>
                @foreach (var course in Catalog.GetCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code — @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn-primary">Submit Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (!string.IsNullOrEmpty(Model.StudentName) && !string.IsNullOrEmpty(Model.StudentId) && Model.CourseId > 0)
        {
            submitted = Catalog.SubmitEnrollmentRequest(Model);
        }
    }
}
```

